  --color-border-focus:#0071e3;
  --color-primary:     #0071e3;
  --color-primary-hover:#0077ed;
  --color-primary-active:#005bbf;
  --color-text:        #1d1d1f;
  --color-text-muted:  #6e6e73;
  --color-help:        #515154;
  --color-error:       #c0392b;
  --color-error-bg:    #fff5f5;
  --color-error-border:#e74c3c;
  --color-success-bg:  #f0faf4;
  --color-success-border:#27ae60;
  --color-success-text:#1a7a44;
  --color-check-bg:    #0071e3;
  --color-check-border:#0071e3;
  --radius-sm:  6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --shadow-card: 0 2px 12px rgba(0,0,0,.08), 0 1px 3px rgba(0,0,0,.06);
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-primary);
  color: #fff;
  font-weight: 600;
  border-radius: var(--radius-sm);
  text-decoration: none;
  z-index: 1000;
  transition: top .15s;
}
.skip-link:focus { top: 1rem; }

/* ── Page layout ── */
body {
  font-family: var(--font);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  padding: 2rem 1rem 4rem;
  -webkit-font-smoothing: antialiased;
}

header {
  text-align: center;
  margin-bottom: 2.5rem;
}

header h1 {
  font-size: clamp(1.6rem, 4vw, 2.4rem);
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--color-text);
}

header p.subtitle {
  margin-top: .5rem;
  font-size: 1.05rem;
  color: var(--color-text-muted);
}

main {
  max-width: 680px;
  margin: 0 auto;
}

/* ── Form card ── */
.quiz-form {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: clamp(1.5rem, 5vw, 2.5rem);
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

/* ── Progress bar ── */
.progress-bar-wrap {
  display: flex;
  align-items: center;
  gap: .75rem;
  font-size: .85rem;
  color: var(--color-text-muted);
}
.progress-bar-track {
  flex: 1;
  height: 6px;
  background: var(--color-border);
  border-radius: 99px;
  overflow: hidden;
}
.progress-bar-fill {
  height: 100%;
  width: 0%;
  background: var(--color-primary);
  border-radius: 99px;
  transition: width .3s ease;
}

/* ── form-field wrapper ── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: .75rem;
}

/* ── Fieldset / legend ── */
fieldset {
  border: none;
  padding: 0;
}

legend {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.4;
  margin-bottom: .25rem;
}

.question-number {
  display: inline-block;
  font-size: .75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--color-primary);
  margin-bottom: .25rem;
}

/* ── Help text ── */
.help-text {
  font-size: .875rem;
  color: var(--color-help);
  line-height: 1.5;
}

/* ── Error text ── */
.error-text {
  font-size: .875rem;
  color: var(--color-error);
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: .35rem;
}
.error-text::before {
  content: "⚠";
  font-size: 1em;
  flex-shrink: 0;
}

/* ── Checkbox options grid ── */
.checkbox-options {
  display: flex;
  flex-direction: column;
  gap: .5rem;
  margin-top: .25rem;
}

/* ── Individual checkbox item ── */
.checkbox-item {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .65rem .875rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: border-color .15s, background .15s, box-shadow .15s;
  user-select: none;
}

.checkbox-item:hover {
  border-color: var(--color-primary);
  background: #f0f7ff;
}

