fieldset[aria-invalid="true"] {
  padding: .75rem;
  border: 1.5px solid var(--color-error-border);
  border-radius: var(--radius-md);
  background: var(--color-error-bg);
}

/* ── Divider ── */
.form-divider {
  border: none;
  border-top: 1px solid var(--color-border);
}

/* ── Submit button ── */
.btn-submit {
  align-self: flex-start;
  padding: .75rem 2rem;
  background: var(--color-primary);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  font-family: var(--font);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background .15s, transform .1s, box-shadow .15s;
  box-shadow: 0 2px 8px rgba(0,113,227,.25);
}
.btn-submit:hover { background: var(--color-primary-hover); box-shadow: 0 4px 12px rgba(0,113,227,.35); }
.btn-submit:active { background: var(--color-primary-active); transform: scale(.98); }
.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

/* ── Results panel ── */
#results-panel {
  display: none;
