  padding: 1.25rem 1.5rem;
  border: 1.5px solid var(--color-success-border);
  background: var(--color-success-bg);
  color: var(--color-success-text);
  font-size: .95rem;
  line-height: 1.6;
}
#results-panel.visible { display: block; }
