(function () {
  "use strict";

  /* ── Quiz answer key ──────────────────────────────────────────── */
  const ANSWER_KEY = {
    q1: ["typescript", "java"],          // statically typed
    q2: ["c", "rust"],                   // systems programming
    q3: ["haskell", "erlang"],           // primarily functional
  };

  /* ── DOM references ── */
  const form         = document.getElementById("quiz-form");
  const progressFill = document.getElementById("progress-fill");
  const progressLabel= document.getElementById("progress-label");
  const resultPanel  = document.getElementById("results-panel");
  const resultMsg    = document.getElementById("result-message");

  /* ── Progress bar: updates as user checks boxes ── */
  function updateProgress() {
    const allGroups = Object.keys(ANSWER_KEY);
    const answered  = allGroups.filter(name => {
      const checked = form.querySelectorAll(`input[name="${name}"]:checked`);
      return checked.length > 0;
    });
    const pct = Math.round((answered.length / allGroups.length) * 100);
    progressFill.style.width = pct + "%";
    progressLabel.textContent = answered.length + " / " + allGroups.length + " answered";
  }

  form.querySelectorAll('input[type="checkbox"]').forEach(cb => {
    cb.addEventListener("change", updateProgress);
  });

  /* ── Validation helpers ── */
  function getCheckedValues(name) {
    return Array.from(form.querySelectorAll(`input[name="${name}"]:checked`))
                .map(el => el.value);
  }

  function arraysMatch(a, b) {
    return a.length === b.length && [...a].sort().join() === [...b].sort().join();
  }

  function setGroupError(fieldsetId, errorId, show) {
    const fs = document.getElementById(fieldsetId);
    const err = document.getElementById(errorId);
    if (show) {
      fs.setAttribute("aria-invalid", "true");
      // add error id to aria-describedby if not already present
      const current = fs.getAttribute("aria-describedby") || "";
      if (!current.includes(errorId)) {
        fs.setAttribute("aria-describedby", (current + " " + errorId).trim());
      }
      err.removeAttribute("hidden");
    } else {
      fs.removeAttribute("aria-invalid");
      err.setAttribute("hidden", "");
      // remove error id from aria-describedby
      const current = (fs.getAttribute("aria-describedby") || "")
        .split(" ").filter(t => t !== errorId).join(" ").trim();
      if (current) {
        fs.setAttribute("aria-describedby", current);
      } else {
        fs.removeAttribute("aria-describedby");
      }
    }
  }

  /* ── Submit handler ── */
  form.addEventListener("submit", function (e) {
    e.preventDefault();

    let firstInvalidFieldset = null;
    let correct = 0;

    // Clear previous result
    resultPanel.classList.remove("visible");
    resultPanel.hidden = true;

    // Evaluate each question
    Object.entries(ANSWER_KEY).forEach(([name, correct_answers], idx) => {
      const fieldsetId = "fieldset-q" + (idx + 1);
      const errorId    = "error-q"    + (idx + 1);
      const selected   = getCheckedValues(name);

      if (selected.length === 0) {
        // No selection — validation error
        setGroupError(fieldsetId, errorId, true);
        if (!firstInvalidFieldset) {
          firstInvalidFieldset = document.getElementById(fieldsetId);
        }
      } else {
        setGroupError(fieldsetId, errorId, false);
        if (arraysMatch(selected, correct_answers)) {
          correct++;
        }
      }
    });

    if (firstInvalidFieldset) {
      // Focus first checkbox in the invalid fieldset
      const firstCb = firstInvalidFieldset.querySelector('input[type="checkbox"]');
      if (firstCb) firstCb.focus();
      return;
    }

    // All answered — show score
    const total = Object.keys(ANSWER_KEY).length;
    const pct   = Math.round((correct / total) * 100);
    let emoji   = correct === total ? "🎉" : correct === 0 ? "😅" : "👍";

    resultMsg.innerHTML =
      `<span class="score">${emoji} ${correct} / ${total}</span><br>` +
      `You scored <strong>${pct}%</strong>. ` +
      (correct === total
        ? "Perfect score — you know your languages!"
        : correct === 0
        ? "Give it another shot — review the answers and try again!"
        : "Good effort! Review the selections to see which were correct.");

    resultPanel.hidden = false;
    resultPanel.classList.add("visible");
    resultPanel.focus();

    // Reset progress fill to 100%
    progressFill.style.width = "100%";
    progressLabel.textContent = total + " / " + total + " answered";
  });

})();
