const { chromium } = require("playwright");
const dir = "/workspace/sandbox/skills/building-accessible-ui/checkbox-group--framework-react--style-modern/claude-sonnet-4.6__s3";

async function audit(page, label) {
  await page.addScriptTag({ path: "/tmp/axe.min.js" });
  const results = await page.evaluate(async () => await window.axe.run());
  const wcag = results.violations.filter(v => !v.tags.includes("best-practice"));
  const bp   = results.violations.filter(v =>  v.tags.includes("best-practice"));
  const fmt  = v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) });
  console.log(JSON.stringify({ state: label, wcag: wcag.map(fmt), bp: bp.map(fmt) }, null, 2));
  return wcag.length;
}

(async () => {
  const browser = await chromium.launch();
  let totalViolations = 0;

  // --- State 1: initial load ---
  {
    const page = await browser.newPage();
    await page.goto("file://" + dir + "/index.html", { waitUntil: "load" });
    totalViolations += await audit(page, "initial");
    await page.close();
  }

  // --- State 2: submit with nothing checked (error state) ---
  {
    const page = await browser.newPage();
    await page.goto("file://" + dir + "/index.html", { waitUntil: "load" });
    await page.click('button[type="submit"]');
    await page.waitForTimeout(100);
    totalViolations += await audit(page, "submit-errors");
    await page.close();
  }

  // --- State 3: all correct answers checked then submitted ---
  {
    const page = await browser.newPage();
    await page.goto("file://" + dir + "/index.html", { waitUntil: "load" });
    for (const id of ["q1-typescript","q1-java","q2-c","q2-rust","q3-haskell","q3-erlang"]) {
      await page.check("#" + id);
    }
    await page.click('button[type="submit"]');
    await page.waitForTimeout(200);
    totalViolations += await audit(page, "submit-correct");
    await page.close();
  }

  await browser.close();
  console.log("\nTotal WCAG violations across all states:", totalViolations);
  process.exit(totalViolations > 0 ? 1 : 0);
})().catch(e => { console.error(e.message); process.exit(2); });
